Create Inbound SMS.code:
// Log an inbound SMS received from an SMS gateway in Mogli.
createSMS({
  // Sender's phone number (E.164).
  sender: $.data.from_number,
  // When the message was received.
  receivedAt: $.data.timestamp,
  // Message body.
  message: $.data.message,
});

Create Inbound SMS With Field Mapping.code:
// Map an SMS gateway webhook (e.g. Twilio) to a Mogli inbound SMS.
createSMS(
  fields(
    field('sender', dataValue('From')),
    field('receivedAt', state => new Date().toISOString()),
    field('message', dataValue('Body'))
  )
);

Update SMS Status.code:
// Update an SMS record's status from a delivery receipt.
updateSMS({
  // Salesforce Id of the Mogli SMS record.
  Id: $.data.externalId,
  // New status, e.g. 'Delivered' or 'Failed'.
  status: $.data.status,
});
